from rcb_client import Robot
import numpy as np

CAMERAS = (
    "robot_r1:zed_link:Camera:0",
    "robot_r1:left_realsense_link:Camera:0",
    "robot_r1:right_realsense_link:Camera:0",
)

def connect():
    return Robot()

def observe(robot, seconds=0.0, video="frames"):
    return robot.get_obs(seconds=seconds, video=video)

def save(result, path):
    return result.save(path)

if __name__ == "__main__":
    robot = connect()
    spec = robot.spec()
    print("SPEC", spec)
    obs = observe(robot)
    save(obs, "/app/runs/initial")
    print("OBS META", obs.meta)
    print("PROPRIO", obs.meta.get("proprio"))
PY
